const d = (typeof query === 'object' && query !== null) ? query : JSON.parse(query);
const errores = [];
const advertencias = [];

// Feriados nacionales: actualizar cada año con el calendario oficial
const FERIADOS = {
  '2026-11-23': 'Día de la Soberanía Nacional',
  '2026-12-08': 'Inmaculada Concepción',
  '2026-12-25': 'Navidad',
  '2027-01-01': 'Año Nuevo',
  '2027-02-08': 'Carnaval',
  '2027-02-09': 'Carnaval',
  '2027-03-24': 'Día de la Memoria',
  '2027-03-25': 'Jueves Santo (día no laborable)',
};

// Fecha y hora actuales en Buenos Aires (para rechazar citas en el pasado, incluida hoy)
const partes = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Argentina/Buenos_Aires', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date());
const p = Object.fromEntries(partes.map(x => [x.type, x.value]));
const hoy = p.year + '-' + p.month + '-' + p.day;
const minAhora = Number(p.hour) * 60 + Number(p.minute);

// Fecha de la cita: formato, existencia, día hábil, feriado y no pasada
const mf = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(d.fecha_cita || '').trim());
if (!mf) {
  errores.push('fecha_cita debe tener formato AAAA-MM-DD');
} else {
  const y = Number(mf[1]), m = Number(mf[2]), dd = Number(mf[3]);
  const f = new Date(Date.UTC(y, m - 1, dd));
  if (f.getUTCFullYear() !== y || f.getUTCMonth() !== m - 1 || f.getUTCDate() !== dd) {
    errores.push('fecha_cita no es una fecha real del calendario');
  } else {
    const dias = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
    const dia = f.getUTCDay();
    if (dia === 0 || dia === 6) {
      errores.push('La fecha cae en ' + dias[dia] + ': el atelier atiende de lunes a viernes');
    }
    if (FERIADOS[mf[0]]) {
      errores.push('La fecha cae en feriado (' + FERIADOS[mf[0]] + '): el atelier no atiende');
    }
    if (mf[0] < hoy) errores.push('La fecha de la cita ya pasó (hoy es ' + hoy + ')');
  }
}

// Hora de la cita: formato y horario de atención 10:00 a 17:30
const mh = /^(\d{2}):(\d{2})$/.exec(String(d.hora_cita || '').trim());
if (!mh || Number(mh[1]) > 23 || Number(mh[2]) > 59) {
  errores.push('hora_cita debe tener formato HH:MM de 24 horas');
} else {
  const min = Number(mh[1]) * 60 + Number(mh[2]);
  if (min < 600 || min > 1050) errores.push('La hora está fuera del horario de atención (10:00 a 17:30)');
  if (mf && mf[0] === hoy && min <= minAhora) errores.push('La hora de la cita ya pasó (hoy son las ' + p.hour + ':' + p.minute + ')');
}

// Fecha de la celebración (opcional): si ambas fechas son completas y la celebración no es posterior a la cita, BLOQUEA; con solo AAAA-MM o formato dudoso solo advierte
const fc = String(d.fecha_celebracion || '').trim();
if (fc) {
  const m = /^(\d{4})-(\d{2})(?:-(\d{2}))?$/.exec(fc);
  if (!m) {
    advertencias.push('fecha_celebracion debe tener formato AAAA-MM-DD o AAAA-MM');
  } else {
    const y = +m[1], mo = +m[2], dd = m[3] ? +m[3] : 1;
    const f = new Date(Date.UTC(y, mo - 1, dd));
    if (f.getUTCFullYear() !== y || f.getUTCMonth() !== mo - 1 || f.getUTCDate() !== dd) {
      advertencias.push('fecha_celebracion no es una fecha real del calendario');
    } else if (mf && fc.length === 10 && fc <= mf[0]) {
      errores.push('La fecha de la celebración debe ser posterior a la de la cita');
    } else if (mf && fc.length === 7) {
      const mesCita = mf[0].slice(0, 7);
      if (fc < mesCita) advertencias.push('El mes de la celebración es anterior al de la cita');
      else if (fc === mesCita) advertencias.push('La celebración es el mismo mes que la cita y sin día no puede determinarse el orden exacto');
    }
  }
}

// Correo
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(String(d.correo || '').trim())) {
  errores.push('El correo electrónico no tiene un formato válido');
}

// Teléfono (Argentina): 10 dígitos = código de área + número
let tel = String(d.telefono || '').replace(/\D/g, '');
tel = tel.replace(/^00/, '')
         .replace(/^549?(?=\d{10}$)/, '')   // quita +54 / +54 9
         .replace(/^0(?=\d{10}$)/, '');     // quita el 0 inicial
if (!/^\d{10}$/.test(tel)) {
  errores.push('El teléfono debe incluir el código de área y tener 10 dígitos, sin 0 ni 15 (ej.: 11 6163 8552 para Buenos Aires)');
}

return JSON.stringify({ valido: errores.length === 0, errores, advertencias });

